"use strict";console.log("할 일 목록 시작!");let workingLength=15,completedLength=60;const workingLengthTag=document.getElementById("working-length"),completedLengthTag=document.getElementById("completed-length"),workingListTag=document.getElementById("working-list"),completedListTag=document.getElementById("completed-list");workingLengthTag.innerHTML=workingLength,completedLengthTag.innerHTML=completedLength;const todoItems=[{workId:100,title:"객체 만들기"},{workId:101,title:"배열 만들기"}];for(const todoItem of todoItems){let e=createTodoArticle(todoItem);workingListTag.innerHTML=workingListTag.innerHTML+e}function createTodoArticle(e){return`<article>
        <input id="work${e.workId}" type="checkbox">
        <label for="work${e.workId}">${e.title}</label>
        </article>`}